    }

    public CounterTraitLayout(Context context, AttributeSet attrs, int defStyleAttr) {
        super(context, attrs, defStyleAttr);
    }

    @Override
    public void setNaTraitsText() {
        counterTv.setText("NA");
    }

    @Override
    public String type() {
        return "counter";
    }

    @Override
    public void init() {
        Button addCounterBtn = findViewById(R.id.addBtn);
        Button minusCounterBtn = findViewById(R.id.minusBtn);
        counterTv = findViewById(R.id.curCount);

        // Add counter
        addCounterBtn.setOnClickListener(new OnClickListener() {
            public void onClick(View arg0) {
                updateCounter(1);
            }
        });

        // Minus counter
        minusCounterBtn.setOnClickListener(new OnClickListener() {
            public void onClick(View arg0) {
                updateCounter(-1);
            }
        });

    }

    /**
     * Applies the given step to the current counter value and saves it.
     * Does nothing when no trait is currently selected (e.g. no traits imported yet),
     * which used to throw a NullPointerException.
     */
    private void updateCounter(int step) {
        final TraitObject currentTrait = getCurrentTrait();

        if (currentTrait == null) {
            return;
        }

        final String traitName = currentTrait.getTrait();
        final Object savedValue = getNewTraits().get(traitName);

        if (savedValue != null && savedValue.toString().equals("NA")) {
            counterTv.setText(Integer.toString(step));
        } else {
            counterTv.setText(Integer.toString(parseCounterValue() + step));
        }

        updateTrait(traitName, "counter", counterTv.getText().toString());
    }

    private int parseCounterValue() {
        try {
            return Integer.parseInt(counterTv.getText().toString());
        } catch (NumberFormatException e) {
            return 0;
        }
    }

    @Override
    public void loadLayout() {
        getEtCurVal().setVisibility(EditText.GONE);
        getEtCurVal().setEnabled(false);

        final TraitObject currentTrait = getCurrentTrait();

        if (currentTrait == null) {
            counterTv.setText("0");
            return;
        }

        final Object savedValue = getNewTraits().get(currentTrait.getTrait());

        if (savedValue == null) {
            counterTv.setText("0");
        } else {
            counterTv.setText(savedValue.toString());
        }
    }

    @Override
    public void deleteTraitListener() {
        final TraitObject currentTrait = getCurrentTrait();

        if (currentTrait != null) {
            removeTrait(currentTrait.getTrait());
        }

        counterTv.setText("0");
    }
}
